// Month and day names and the "Today:" date pattern.
template <typename Declaring>
struct MonthCalendarFormatProviderCapability {
    PropertyCell<DateTimeFormatProvider, MonthCalendarFormatProviderCapability<Declaring>> format_provider{DateTimeFormatProvider::english_united_states()};

    static void assign(MonthCalendarFormatProviderCapability& capability, DateTimeFormatProvider incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.format_provider), incoming);
        if (!capability.format_provider.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.format_provider));
    }
};

// Every MonthCalendar capability, in the order the declaring class takes them.
template <typename Declaring>
struct MonthCalendarCapabilities : public ShowTodayCapability<Declaring>,
                                   public ShowTodayCircleCapability<Declaring>,
                                   public ShowWeekNumbersCapability<Declaring>,
                                   public FirstDayOfWeekCapability<Declaring>,
                                   public CalendarDimensionsCapability<Declaring>,
                                   public MaxSelectionCountCapability<Declaring>,
                                   public ScrollChangeCapability<Declaring>,
                                   public MonthCalendarFormatProviderCapability<Declaring>,
                                   public FontCapability<Declaring> {
    MonthCalendarCapabilities() : FontCapability<Declaring>(FontSpec{FontRole::control, 10.5, 400, false, 0.12}) {}
};

